export function getBrotMarketsErrorMessage(code: BrotMarketsError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (brotMarketsErrorMessages as Record<BrotMarketsError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isBrotMarketsError<TProgramErrorCode extends BrotMarketsError>(
  error: unknown,
  transactionMessage: { instructions: Record<number, { programAddress: Address }> },
  code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(error, transactionMessage, BROT_MARKETS_PROGRAM_ADDRESS, code);
}
